<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowUpRight, RefreshCw, Layers, Database } from 'lucide-vue-next'
import { useQuery } from '../lib/query'
import { num,pct,direction,stamp,metricLabel,frequency,grades,record,numeric } from '../lib/format'
import type { Overview, BoardRow } from '../lib/types'
import PageState from '../components/PageState.vue'
import Badge from '../components/Badge.vue'
const route=useRoute(),horizon=ref(1),theme=ref(''),filter=ref(''),offset=ref(0),limit=100
const q=useQuery<Overview>(()=>`/api/workspace/overview?horizon=${horizon.value}&offset=${offset.value}&limit=${limit}${theme.value?'&theme='+encodeURIComponent(theme.value):''}`)
const market=useQuery<Record<string,unknown>>('/api/market-context'),sectors=useQuery<Record<string,unknown>>('/api/sectors/market')
const marketItems=computed(()=>{const items=market.data.value?.latest_view??[];return Array.isArray(items)?items.map(record).filter(x=>x.context_kind==='index'||x.kind==='index').slice(0,4):[]})
const sectorItems=computed(()=>{const data=sectors.data.value;const rows=data?.boards??[];return Array.isArray(rows)?rows.map(record).filter(x=>x.board_type!=='market').slice(0,12):[]})
const rows=computed(()=>q.data.value?.rows.filter(row=>(!filter.value||row.grade===filter.value))??[])
const breadth=computed(()=>{const list=q.data.value?.rows??[];return{up:list.filter(r=>(r.return_1d??0)>0).length,down:list.filter(r=>(r.return_1d??0)<0).length,missing:list.filter(r=>r.return_1d==null).length}})
const title=computed(()=>route.path==='/decision/1430'?'14:30 尾盘研究':route.path==='/boards'?'行业与概念板块':'市场总览')
function resetPage(){offset.value=0}
function changePage(delta:number){offset.value=Math.max(0,offset.value+delta*limit)}
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">MARKET OVERVIEW / ETF</p><h1>{{title}}</h1><p>先看市场，再看证据。技术状态与历史频率分开呈现，不制造确定性。</p></div><div class="heading-actions"><span class="muted" style="font-size:11px">快照 {{stamp(q.data.value?.generated_at)}}</span><button class="button" :disabled="q.loading.value" @click="q.reload();market.reload();sectors.reload()"><RefreshCw :size="14"/>重新读取</button></div></div><div class="section-tabs"><RouterLink to="/" :class="{active:route.path==='/'}">市场总览</RouterLink><RouterLink to="/boards" :class="{active:route.path==='/boards'}">行业板块</RouterLink><RouterLink to="/decision/1430" :class="{active:route.path==='/decision/1430'}">14:30 研究模式</RouterLink></div><div v-if="route.path==='/decision/1430'" class="notice warning-notice">14:30 历史策略尚未取得资格。这里展示同一决策快照，不生成第二套买卖结论；盘后信息不能反用于盘中。</div><div class="cards"><template v-if="marketItems.length"><article v-for="item in marketItems" :key="String(item.context_id??item.label)" class="stat-card"><div class="label">{{item.label}}<ArrowUpRight :size="15"/></div><div class="value">{{num(item.observed_value??item.value??record(item.snapshot).observed_value)}}<span class="delta" :class="direction(numeric(item.today_pct_change??record(item.snapshot).today_pct_change))">{{pct(numeric(item.today_pct_change??record(item.snapshot).today_pct_change)==null?null:Number(item.today_pct_change??record(item.snapshot).today_pct_change)/100)}}</span></div><small>{{item.source??record(item.snapshot).source??'缺少来源'}} · {{item.freshness??record(item.snapshot).freshness??'待核验'}}</small></article></template><template v-else><article class="stat-card"><div class="label">跟踪 ETF 数量<Database :size="16"/></div><div class="value">{{num(q.data.value?.total,0)}}</div><small>不是全市场证券总量</small></article><article class="stat-card"><div class="label">当前页上涨 / 下跌</div><div class="value"><span class="bull">{{breadth.up}}</span><span class="muted"> / </span><span class="bear">{{breadth.down}}</span></div><small>缺失 {{breadth.missing}} · 不计入平盘</small></article><article class="stat-card"><div class="label">研究期限</div><div class="value">1 / 3 / 5 / 10</div><small>交易日 · 非自然日</small></article><article class="stat-card"><div class="label">指数上下文<Layers :size="16"/></div><div class="value">待同步</div><small>真实指数数据缺失时不填示例数字</small></article></template></div><div v-if="sectorItems.length" class="card"><div class="card-header"><div><h2>板块温度</h2><p>板块数据来自独立快照；ETF 代理不冒充成分股广度。</p></div><Badge :value="String(sectors.data.value?.freshness??'research')"/></div><div class="sector-grid"><article v-for="s in sectorItems" :key="String(s.sector_name??s.name)" class="sector-tile" :class="direction(s.sector_pct_change)"><strong>{{s.sector_name??s.name}}</strong><span class="numeric">{{pct(numeric(s.sector_pct_change)==null?null:Number(s.sector_pct_change)/100)}}</span><small>{{record(s.breadth).trade_date??s.coverage_note??'数据时间未知'}}</small></article></div></div><div v-else-if="route.path==='/boards'" class="notice">{{sectors.error.value||'尚无行业/概念快照。可在设置中提交数据更新任务；页面不会等待外部抓取。'}}</div><div class="card"><div class="card-header"><div><h2>ETF 决策快照</h2><p>唯一五档状态 · 指标解释 · 未校准预测仅为历史频率</p></div><Badge :value="q.data.value?.contains_mock?'mock':q.data.value?.freshness_at_capture"/></div><div class="toolbar"><label>行业<select v-model="theme" @change="resetPage"><option value="">全部行业</option><option v-for="t in q.data.value?.themes" :key="t">{{t}}</option></select></label><label>状态<select v-model="filter"><option value="">全部状态</option><option v-for="grade in grades" :key="grade">{{grade}}</option><option>数据异常</option></select></label><label>预测期限<select v-model.number="horizon"><option v-for="h in [1,3,5,10]" :key="h" :value="h">{{h}} 个交易日</option></select></label></div><PageState :loading="q.loading.value" :error="q.error.value" :empty="!rows.length" @retry="q.reload"><template #action><RouterLink to="/settings" class="button primary">查看数据状态</RouterLink></template><div class="table-scroll"><table><thead><tr><th>ETF / 行业</th><th class="numeric">快照价格</th><th class="numeric">当日涨跌</th><th>研究状态</th><th>量能</th><th>MACD</th><th>KDJ</th><th>RSI</th><th class="numeric">{{horizon}}日情景收益</th><th class="numeric">历史上涨频率</th></tr></thead><tbody><tr v-for="row in rows" :key="row.ts_code"><td class="name-cell"><RouterLink :to="'/etf/'+row.ts_code">{{row.name}}</RouterLink><small>{{row.ts_code}} · {{row.theme_l1??'未分类'}}</small></td><td class="numeric">{{num(row.price,3)}}</td><td class="numeric" :class="direction(row.return_1d)">{{pct(row.return_1d)}}</td><td><span class="grade" :data-grade="row.grade" :title="row.grade_reason">{{row.grade}}</span></td><td>{{metricLabel(row.volume)}}</td><td>{{metricLabel(row.macd)}}</td><td>{{metricLabel(row.kdj)}}</td><td>{{num(row.rsi?.value,1)}}</td><td class="numeric forecast">{{pct(row.forecasts?.[horizon]?.expected_return)}}</td><td class="numeric">{{frequency(row.forecasts?.[horizon])}}<small>n={{row.forecasts?.[horizon]?.sample_count??'—'}}</small></td></tr></tbody></table></div></PageState><div class="table-footer"><span>已加载 {{rows.length}} / {{q.data.value?.total??0}} · 仅跟踪池 · 快照不等于实时行情</span><div class="button-row"><button class="button small" :disabled="offset===0" @click="changePage(-1)">上一页</button><button class="button small" :disabled="offset+limit>=(q.data.value?.total??0)" @click="changePage(1)">下一页</button></div></div></div></section></template>
